document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("theme-toggler"),t=document.getElementsByTagName("html")[0],a=localStorage.getItem("theme")||"dark";t.dataset.theme=a,e.checked="dark"===t.dataset.theme,t.dataset.theme=localStorage.theme||"dark",localStorage.setItem("theme",t.dataset.theme),e.addEventListener("click",(()=>{t.dataset.theme=e.checked?"dark":"light",localStorage.theme=t.dataset.theme}))});
